<?php
namespace App\Services; use CodeIgniter\HTTP\Files\UploadedFile; use DomainException; use finfo;
class AssistanceDocumentStorage { public function store(UploadedFile $f):array{$c=config('VerificationAssistance');if($f->hasMoved()||!$f->isValid()||$f->getError()!==UPLOAD_ERR_OK||$f->getSize()<1||$f->getSize()>$c->maxFileSizeBytes)throw new DomainException('Upload a complete PDF, JPG, or PNG document under 5 MiB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f->getTempName());$ext=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png'][$mime]??null;if(!$ext||!in_array(strtolower(pathinfo($f->getClientName(),PATHINFO_EXTENSION)),[$ext,$ext==='jpg'?'jpeg':$ext],true))throw new DomainException('Upload a valid PDF, JPG, or PNG document.');$dir=$c->storageDirectory;if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new \RuntimeException('Private document storage is unavailable.');$stored=bin2hex(random_bytes(32)).'.'.$ext;if(!$f->move($dir,$stored,false))throw new \RuntimeException('Document storage failed.');$path=$dir.DIRECTORY_SEPARATOR.$stored;$hash=hash_file('sha256',$path);if(!$hash){@unlink($path);throw new \RuntimeException('Document verification failed.');}$name=mb_substr(basename(str_replace('\\','/',$f->getClientName())),0,255);return ['document_name'=>$name?:'supporting-document.'.$ext,'document_stored_name'=>$stored,'document_mime_type'=>$mime,'document_size'=>$f->getSize(),'document_sha256'=>$hash];} public function path(string $stored):string{$c=config('VerificationAssistance');if(!preg_match('/\A[a-f0-9]{64}\.(pdf|jpg|png)\z/',$stored))throw new DomainException('Document unavailable.');$p=realpath($c->storageDirectory.DIRECTORY_SEPARATOR.$stored);$d=realpath($c->storageDirectory);if(!$p||!$d||!str_starts_with($p,$d.DIRECTORY_SEPARATOR))throw new DomainException('Document unavailable.');return $p;}}
